#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <float.h>

extern "C" __global__
void max_reduce_kernel(const __half* __restrict__ input,
                       __half* __restrict__ output,
                       int dim0, int dim1, int dim2,
                       int reduce_dim) {
    int total_out;
    if (reduce_dim == 0) total_out = dim1 * dim2;
    else if (reduce_dim == 1) total_out = dim0 * dim2;
    else total_out = dim0 * dim1;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_out) return;

    __half max_val = __float2half(-FLT_MAX);

    if (reduce_dim == 0) {
        // reduce over dim0 -> output size dim1*dim2
        int j = idx / dim2;          // index in dim1
        int k = idx % dim2;          // index in dim2
        for (int r = 0; r < dim0; ++r) {
            int offset = r * dim1 * dim2 + j * dim2 + k;
            __half v = input[offset];
            max_val = __hgt(v, max_val) ? v : max_val;
        }
        output[idx] = max_val;
    } else if (reduce_dim == 1) {
        // reduce over dim1 -> output size dim0*dim2
        int i = idx / dim2;          // index in dim0
        int k = idx % dim2;          // index in dim2
        for (int r = 0; r < dim1; ++r) {
            int offset = i * dim1 * dim2 + r * dim2 + k;
            __half v = input[offset];
            max_val = __hgt(v, max_val) ? v : max_val;
        }
        output[idx] = max_val;
    } else {
        // reduce over dim2 -> output size dim0*dim1
        int i = idx / dim1;          // index in dim0
        int j = idx % dim1;          // index in dim1
        for (int r = 0; r < dim2; ++r) {
            int offset = i * dim1 * dim2 + j * dim2 + r;
            __half v = input[offset];
            max_val = __hgt(v, max_val) ? v : max_val;
        }
        output[idx] = max_val;
    }
}

void max_reduce_cuda(torch::Tensor input,
                     torch::Tensor output,
                     int64_t reduce_dim) {
    const int dim0 = input.size(0);
    const int dim1 = input.size(1);
    const int dim2 = input.size(2);

    const int threads = 256;
    int total_out;
    if (reduce_dim == 0) total_out = dim1 * dim2;
    else if (reduce_dim == 1) total_out = dim0 * dim2;
    else total_out = dim0 * dim1;
    const int blocks = (total_out + threads - 1) / threads;

    max_reduce_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        dim0, dim1, dim2,
        static_cast<int>(reduce_dim)
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
